def sum_in_range(l, r):
    lower = min(l, r)
    upper = max(l, r)

    # Find the first odd number in the range
    if lower % 2 == 0:
        first_odd = lower + 1
    else:
        first_odd = lower

    # Check if there are any odd numbers in the range
    if first_odd > upper:
        return 0

    # Find the last odd number in the range
    if upper % 2 == 0:
        last_odd = upper - 1
    else:
        last_odd = upper

    # Calculate the number of terms and the sum
    n = ((last_odd - first_odd) // 2) + 1
    total = n * (first_odd + last_odd) // 2

    return total

