def find_max(words):
    if not words:
        return ''
    max_count = -1
    candidates = []
    for word in words:
        unique = len(set(word))
        if unique > max_count:
            max_count = unique
            candidates = [word]
        elif unique == max_count:
            candidates.append(word)
    return min(candidates)
