import math

def eulerian_num(n, m):
    if n == 0:
        return 1 if m == 0 else 0
    if m < 0 or m >= n:
        return 0
    total = 0
    for k in range(m + 1):
        term = ((-1) ** k) * math.comb(n + 1, k) * ((m + 1 - k) ** n)
        total += term
    return total
