import math

def sum_of_proper_divisors(n):
    if n == 1:
        return 0
    total = 1
    sqrt_n = int(math.sqrt(n))
    for i in range(2, sqrt_n + 1):
        if n % i == 0:
            if i == n // i:
                total += i
            else:
                total += i + n // i
    return total

def amicable_numbers_sum(limit):
    total = 0
    for n in range(2, limit + 1):
        s = sum_of_proper_divisors(n)
        if s == n:
            continue
        if s > n and s <= limit:
            sum_s = sum_of_proper_divisors(s)
            if sum_s == n:
                total += n + s
    return total
