def is_multiply_prime(a):
    if a < 2:
        return False
    factors = []
    # Handle the case of 2
    while a % 2 == 0:
        factors.append(2)
        a //= 2
    # Check for odd factors
    i = 3
    while i * i <= a:
        while a % i == 0:
            factors.append(i)
            a //= i
        i += 2
    # If remaining a is a prime number greater than 2
    if a > 1:
        factors.append(a)
    return len(factors) == 3

