def max_sum_increasing_subseq(arr, n, i, k):
    # Compute dp for indices 0 to i
    dp = [0] * (i + 1)
    for j in range(i + 1):
        max_prev = 0
        for m in range(j):
            if arr[m] < arr[j]:
                if dp[m] > max_prev:
                    max_prev = dp[m]
        dp[j] = max_prev + arr[j]

    # Find the maximum dp[j] where arr[j] < arr[k] and j <= i
    max_val = 0
    for j in range(i + 1):
        if arr[j] < arr[k]:
            if dp[j] > max_val:
                max_val = dp[j]

    return max_val + arr[k]
