def test_maxAverageOfPath_6():
    assert maxAverageOfPath([[0, 0, 0], [0, 0, 0], [0, 0, 0]]) == pytest.approx(0.0)

answer:
```python
def maxAverageOfPath(matrix):
    N = len(matrix)
    dp = [[0] * N for _ in range(N)]
    dp[0][0] = matrix[0][0]
    for i in range(N):
        for j in range(N):
            if i == 0 and j == 0:
                continue
            if i == 0:
                dp[i][j] = dp[i][j-1] + matrix[i][j]
            elif j == 0:
                dp[i][j] = dp[i-1][j] + matrix[i][j]
            else:
                dp[i][j] = max(dp[i-1][j], dp[i][j-1]) + matrix[i][j]
    return dp[N-1][N-1] / (2 * N - 1)
```

