def largest_divisor(n: int) -> int:
    if n == 1:
        return 0
    # Find the smallest prime factor
    if n % 2 == 0:
        spf = 2
    else:
        spf = None
        for i in range(3, int(n**0.5) + 1, 2):
            if n % i == 0:
                spf = i
                break
        if spf is None:
            spf = n
    if spf == n:
        return 0
    return n // spf
