def is_nested(string):
    stack = []
    pairs = []
    for i, char in enumerate(string):
        if char == '[':
            stack.append(i)
        else:
            if stack:
                open_idx = stack.pop()
                pairs.append((open_idx, i))
    # Check for nested pairs
    for i in range(len(pairs)):
        a, b = pairs[i]
        for j in range(len(pairs)):
            if i == j:
                continue
            c, d = pairs[j]
            if c < a and d > b:
                return True
    return False
