def max_sum_increasing_subseq(arr, n, i, k):
    # Compute dp for prefix up to index i
    dp = [0] * (i + 1)
    for j in range(i + 1):
        dp[j] = arr[j]
        for m in range(j):
            if arr[m] < arr[j]:
                if dp[m] + arr[j] > dp[j]:
                    dp[j] = dp[m] + arr[j]

    # Find the maximum dp[j] where arr[j] < arr[k]
    max_prev = float('-inf')
    found = False
    for j in range(i + 1):
        if arr[j] < arr[k]:
            if dp[j] > max_prev:
                max_prev = dp[j]
                found = True

    if found:
        return max_prev + arr[k]
    else:
        return arr[k]
