def is_simple_power(x, n):
    if x == 0:
        return n == 0
    if x == 1:
        return n != 0
    if n == 0:
        return False
    if n == 1:
        return x == 1
    abs_x = abs(x)
    abs_n = abs(n)
    current = abs_n
    k = 1
    while current < abs_x:
        current *= abs_n
        k += 1
    if current != abs_x:
        return False
    # Now check the sign
    if x < 0 and n < 0:
        return k % 2 == 1
    elif x < 0 and n > 0:
        return False
    elif x > 0 and n < 0:
        return k % 2 == 0
    else:
        return True
