import math

def perfect_squares(a, b):
    start = min(a, b)
    end = max(a, b)
    if end < 0:
        return []
    if start < 0:
        lower_n = 1
    else:
        lower_n = max(1, int(math.ceil(math.sqrt(start))))
    upper_n = int(math.floor(math.sqrt(end)))
    if lower_n > upper_n:
        return []
    else:
        return [n * n for n in range(lower_n, upper_n + 1)]
