def perfect_squares(start, end):
    min_val = min(start, end)
    max_val = max(start, end)
    squares = []
    n = 0
    while True:
        square = n * n
        if square >= max_val:
            break
        if square >= min_val:
            squares.append(square)
        n += 1
    return squares

