def magic_square_test(matrix):
    if not matrix or len(matrix) == 0:
        return False
    rows = len(matrix)
    cols = len(matrix[0])
    for row in matrix:
        if len(row) != cols:
            return False
    if rows != cols:
        return False
    target_sum = sum(matrix[0])
    # Check rows
    for row in matrix:
        if sum(row) != target_sum:
            return False
    # Check columns
    for col in range(cols):
        column_sum = 0
        for row in range(rows):
            column_sum += matrix[row][col]
        if column_sum != target_sum:
            return False
    # Check diagonals
    diag1 = 0
    diag2 = 0
    for i in range(rows):
        diag1 += matrix[i][i]
        diag2 += matrix[i][rows - 1 - i]
    if diag1 != target_sum or diag2 != target_sum:
        return False
    return True
