def sumofFactors(n):
    if n % 2 != 0:
        return 0
    m = n // 2
    sum_factors = 0
    for i in range(1, int(m**0.5) + 1):
        if m % i == 0:
            if i == m // i:
                sum_factors += i
            else:
                sum_factors += i + m // i
    return sum_factors * 2
