def get_total_number_of_sequences(m, n):
    if n == 0:
        return 0
    dp_prev = [0] * (m + 1)
    for v in range(1, m + 1):
        dp_prev[v] = 1
    for i in range(2, n + 1):
        prefix_sum = [0] * (m + 1)
        for k in range(1, m + 1):
            prefix_sum[k] = prefix_sum[k - 1] + dp_prev[k]
        dp_current = [0] * (m + 1)
        for v in range(1, m + 1):
            max_u = v // 2
            if max_u >= 1:
                dp_current[v] = prefix_sum[max_u]
            else:
                dp_current[v] = 0
        dp_prev = dp_current
    return sum(dp_prev[1:])
```

