def minPath(grid, k):
    n = len(grid)
    heap = []
    # Initialize the heap with all possible starting positions
    for i in range(n):
        for j in range(n):
            heapq.heappush(heap, ([grid[i][j]], (i, j)))

    while heap:
        current_path, (x, y) = heapq.heappop(heap)
        if len(current_path) == k:
            return current_path
        # Generate next steps
        for dx, dy in [(-1, 0), (1, 0), (0, -1), (0, 1)]:
