def prod_signs(arr):
    if not arr:
        return None
    sum_mag = 0
    has_zero = False
    count_neg = 0
    for num in arr:
        sum_mag += abs(num)
        if num == 0:
            has_zero = True
        elif num < 0:
            count_neg += 1
    if has_zero:
        return 0
    product_sign = -1 if count_neg % 2 else 1
    return product_sign * sum_mag
