import math

def amicable_numbers_sum(n):
    def sum_of_proper_divisors(x):
        if x == 1:
            return 0
        total = 1
        sqrt_x = int(math.sqrt(x))
        for i in range(2, sqrt_x + 1):
            if x % i == 0:
                if i == x // i:
                    total += i
                else:
                    total += i + x // i
        return total

    total_sum = 0
    for i in range(2, n + 1):
        s = sum_of_proper_divisors(i)
        if s != i and s <= n and s > i:
            if sum_of_proper_divisors(s) == i:
                total_sum += i + s
    return total_sum
