def get_median(A, B, n):
    low = 0
    high = n
    while low <= high:
        i = (low + high) // 2
        j = n - i
        # Compute max of left parts
        A_left_max = -float('inf')
        if i > 0:
            A_left_max = A[i-1]
        B_left_max = -float('inf')
        if j > 0:
            B_left_max = B[j-1]
        left_max = max(A_left_max, B_left_max)
        # Compute min of right parts
        A_right_min = float('inf')
        if i < n:
            A_right_min = A[i]
        B_right_min = float('inf')
        if j < n:
            B_right_min = B[j]
        right_min = min(A_right_min, B_right_min)
        if left_max <= right_min:
            return (left_max + right_min) / 2
        elif A_left_max > B_right_min:
            high = i - 1
        else:
            low = i + 1
    return (left_max + right_min) / 2

