        if col_sum != target:
            return False
    # Check diagonal sums
    diag1 = 0
    diag2 = 0
    for i in range(n):
        diag1 += matrix[i][i]
        diag2 += matrix[i][n - 1 - i]
    if diag1 != target or diag2 != target:
        return False
    return True

