import itertools

def is_multiply_prime(a):
    if a < 30:
        return False

    def sieve(n):
        if n < 2:
            return []
        sieve_list = [True] * (n + 1)
        sieve_list[0] = sieve_list[1] = False
        for i in range(2, int(n ** 0.5) + 1):
            if sieve_list[i]:
                sieve_list[i*i : n+1 : i] = [False] * len(sieve_list[i*i : n+1 : i])
        primes = [i for i, is_prime in enumerate(sieve_list) if is_prime]
        return primes

    primes = sieve(a)
    for triplet in itertools.combinations(primes, 3):
        if triplet[0] * triplet[1] * triplet[2] == a:
            return True
    return False
```

