def valid_date(date):
    """Validates a date string and returns True if the date is valid, otherwise False.

    The date is valid if:
    1. The date string is not empty.
    2. The date is in the format mm-dd-yyyy.
    3. The month is between 1 and 12.
    4. The day is valid for the given month:
       - 1-31 for months with 31 days (1,3,5,7,8,10,12)
       - 1-30 for months with 30 days (4,6,9,11)
       - 1-29 for February
    """
    if not date:
        return False

    parts = date.split('-')
    if len(parts) != 3:
        return False

    if not all(part.isdigit() for part in parts):
        return False

    month, day, year = map(int, parts)

    if month < 1 or month > 12:
        return False

    if month in [1, 3, 5, 7, 8, 10, 12]:
        if day < 1 or day > 31:
            return False
    elif month in [4, 6, 9, 11]:
        if day < 1 or day > 30:
            return False
    elif month == 2:
        if day < 1 or day > 29:
            return False
    else:
        return False

    return True
