def maxAverageOfPath(matrix):
    N = len(matrix)
    # Initialize a DP table to store the maximum sum to reach each cell
    dp = [[0] * N for _ in range(N)]
    dp[0][0] = matrix[0][0]

    for i in range(N):
        for j in range(N):
