                continue
            # If in the first row, can only come from the left
            if i == 0:
                dp[i][j] = dp[i][j-1] + matrix[i][j]
            # If in the first column, can only come from above
            elif j == 0:
                dp[i][j] = dp[i-1][j] + matrix[i][j]
            # Otherwise, take the max of the cell above or to the left
            else:
                dp[i][j] = max(dp[i-1][j], dp[i][j-1]) + matrix[i][j]

    # Calculate the average using the total sum and the number of cells
    total_cells = 2 * N - 1
    return dp[N-1][N-1] / total_cells
