def is_nested(string):
    '''
    Create a function that takes a string as input which contains only square brackets.
    The function should return True if and only if there is a valid subsequence of brackets 
    where at least one bracket in the subsequence is nested.
    '''
    if not string:
        return False

    # Use a stack to check for valid nesting
    stack = []
    nested = False
    for char in string:
        if char == '[':
            stack.append(char)
        elif char == ']':
            if stack:
                stack.pop()
                if len(stack) > 0:
                    nested = True
            else:
                # Unmatched closing bracket
                return False

    # If the stack is not empty, the string is not properly nested
    if stack:
        return False

    return nested
