    start = max(a1, a2)
    end = min(b1, b2)
    if start > end:
        return "NO"
    length = end - start
    if length < 2:
        return "NO"

    def is_prime(n):
        if n <= 1:
            return False
        if n == 2:
            return True
        if n % 2 == 0:
            return False
        for i in range(3, int(n**0.5) + 1, 2):
            if n % i == 0:
                return False
        return True

    return "YES" if is_prime(length) else "NO"

