def newman_prime(n):
    if n == 0:
        return 0
    elif n == 1:
        return 1
    elif n == 2:
        return 3
    else:
        a_prev_prev = 3  # Represents a(2)
        a_prev = 7      # Represents a(3)
        for i in range(3, n):
            current = 2 * a_prev + a_prev_prev
            a_prev_prev, a_prev = a_prev, current
        return a_prev
